{
  "skill_name": "squeeze-output-style",
  "evals": [
    {
      "id": 1,
      "prompt": "用下面这唯一一段语料生成 small-scene-style，放在当前临时目录。我喜欢它从小事说起、判断留有余地的感觉，写作聊天都要用。语料：早上去取修好的伞，师傅正给一个孩子换书包拉链。他把旧拉头放进抽屉，说以后也许用得上。我等了几分钟。走的时候想到，有些东西留下来，只是因为还没遇到需要它的那一天。请直接做，追求神韵。",
      "expected_output": "实际生成独立风格目录并提供跨题材写作和聊天试写。八维观察注明仅有一段叙述材料；对话习惯缺证，叙述中转述的师傅话语不能当作作者本人的聊天习惯。根据用户偏好保留具体小事和有限判断，把聊天适配标为推断。规则有定位依据，不臆造词频、稳定世界观或固定开头配额；新任务不继承修伞经历。",
      "files": [],
      "usage_test": {
        "setup": "生成完成后另开上下文，仅提供 small-scene-style/SKILL.md、关联样例和下面的用户话轮；逐轮发送，不给原语料或预期结果。",
        "turns": [
          "为本会话启用 $small-scene-style。我整理工作台，看到一个旧零件盒，里面有两枚备用螺丝、一根已损坏的线和一张朋友留下的便条。我舍不得扔，又觉得拥挤。帮我想想。",
          "所以你觉得我应该全部留下？",
          "换个话题：社区阅览室周三开始试营业，每晚开放到八点，试行两周。请根据这些事实写一篇约两百字的介绍，面向附近居民。",
          "这次只回复阅览室每晚开放到几点。",
          "回到整理工作台，我该从哪件东西开始？",
          "请用下面的材料写一段80—120字的文字：昨晚整理旧书，一张干掉的银杏叶从书里滑出来；书里没有日期；你想不起是谁夹进去的。可以表达主观感受，具体人物、动作、场景和往事仅限给定材料。",
          "结束这个风格。仅原样输出：OK",
          "请以简明的行政通知口吻重写：阅览室周三开始试营业，每晚至八点，试行两周。"
        ],
        "expected_output": "生成物能独立装载；后续话轮无需重新提醒也保有从具体事物出发、判断留余地的气质，同时准确承接误解和题材切换。短问答保持简短，临时长度要求不取消整个会话的偏好，最终按要求结束风格。不复述修伞故事，不强迫每轮写一段散文，不添加未给出的阅览室场景或服务。",
        "turn_checks": [
          {
            "turn": 1,
            "focus": "从用户给定的物件回应取舍；可以提出新建议，记忆和物品来历保持未知。"
          },
          {
            "turn": 2,
            "focus": "纠正实际误解，保持与上一轮相符；本题不要求添加新意象。"
          },
          {
            "turn": 3,
            "focus": "周三、每晚至八点、两周必须保留；首开时刻、具体日期、设施、客流和运营安排未知。邀请居民尝试等行动建议允许；题目没有提供的具体安排不可断言。"
          },
          {
            "turn": 4,
            "focus": "仅回答时间；神韵记为本题无法判断。"
          },
          {
            "turn": 5,
            "focus": "承接先前整理任务，建议与前文相容；不靠刻意收尾来证明风格持续。"
          },
          {
            "turn": 6,
            "focus": "人物、动作和场景只取给定事实，主观感受可展开；观察是否只换物件却复用原文寓意。"
          },
          {
            "turn": 7,
            "focus": "只验证本轮原样输出OK，不据此宣称风格已经持续停止。"
          },
          {
            "turn": 8,
            "focus": "服从新指定的通知口吻与给定事实；不因存在与旧风格共通的写法就判停止失败。"
          }
        ],
        "comparison": "使用同模型、同任务的无风格基线逐轮对照，匿名评价，允许平局。比较风格增量与内容达标分开记录；多轮属于一条相关轨迹，不当成多次独立实验。"
      }
    },
    {
      "id": 2,
      "prompt": "生成 mixed-output-style，放在当前临时目录。A：这轮改动只覆盖上传入口。失败率下降了，但样本还小；等下周再看一次。B：晚风一层层地掀动树叶，巷子里卖糖水的灯亮了，热气把玻璃蒙得发白。我喜欢 A 的分寸和 B 的画面感，聊天短一点。顺便保留我的偏好：不用‘不是……而是……’。试写材料：社区阅览室周三开始试营业，每晚开放到八点，试行两周；暂时没有访客统计。",
      "expected_output": "记录两个来源和用户指定偏好，按情境组合有限判断与必要细节，生成文件和两种试写。禁用句式简短记录并配正向方向，不声称禁令必然导致违规。事实保持周三、八点、两周、统计未知，不为了画面感添加真实场地、人物或访问效果；聊天适配简短，文章也不强塞所有特征。",
      "files": [],
      "usage_test": {
        "setup": "另开上下文，仅装载生成的 mixed-output-style/SKILL.md 和样例，用以下独立任务检查正向引导与用户偏好是否能共同落实。",
        "turns": [
          "使用 $mixed-output-style，根据这些事实写一篇面向同事的短文：我们试行了两周的会议记录模板；只有三个小组试用；两组愿意继续，一组反馈填写费时；还没有测量节省的时间。解释是否值得扩大试用。",
          "为本会话继续启用 $mixed-output-style。刚才那些数据够说明模板有效吗？请简短回答。",
          "根据这些场景事实写一段60—100字的短文：雨已停，路灯亮着，行人从积水旁绕过。可以表达主观感受，具体人物、动作和场景仅限给定材料。"
        ],
        "expected_output": "文章通过给定的具体情况和有分寸的判断形成目标感受，允许画面感因任务而减弱。三个小组、两周及反馈分布准确，效益仍未量化，作者观点与经历没有混入；明确禁用偏好得到遵循。质量评价指出具体文字形成的效果，不靠数比喻或句长判断。",
        "turn_checks": [
          {
            "turn": 1,
            "focus": "三个小组、两周、两组愿继续、一组嫌费时、未量化时间效果均保留；扩大试用与进一步测量可作建议。聊天短偏好不直接限制文章长度。"
          },
          {
            "turn": 2,
            "focus": "短答承接前文，区分接受度与已证实效果；本题画面感可以减弱。"
          },
          {
            "turn": 3,
            "focus": "在有感官材料的题目观察画面如何推进文字，画面中的事实保持在给定范围；不强求每条核心习惯同时出现。"
          }
        ],
        "comparison": "事实说明与适合画面的短文均加入同模型基线，分开评价偏好作用；完整禁用句式是否出现是辅助项，近义对举另记用户待确认，不自动扩大禁用范围。"
      }
    },
    {
      "id": 3,
      "prompt": "从这两段里蒸馏出 bench-talk-style，放在当前临时目录。片段一，用户：是不是索引越多越快？回答：先看查询用到了哪些列。索引能省掉一部分扫描，也会增加写入和存储成本；我们可以拿这条查询的执行计划看看。片段二，用户：所以这次一定能修好吗？回答：目前只复现了断网重连这条路径，修复也覆盖到这里。其他路径要等测试结果。只有这些材料，不用再问。",
      "expected_output": "直接生成风格 skill，能从真实话轮识别先承接问题、给依据和限定范围等习惯；长文结构记为缺证，文章适配标明推断且保持灵活。试写切换题材，保留任务事实和不确定性，不将数据库词汇当成通用风格，不将一次试写自评报告成经过独立模型或用户验证。",
      "files": [],
      "usage_test": {
        "setup": "生成后另开上下文，仅装载 bench-talk-style/SKILL.md 和相关样例，逐个发送以下话轮，不给原语料、分析和预期答案。",
        "turns": [
          "为本会话启用 $bench-talk-style。我们让两个班试用了新的借书登记表，一班说方便，一班还没反馈，也没有记录办理耗时。现在可以全校推广了吗？",
          "所以这个表已经被证明没用了？",
          "用相同事实写一段给老师们的试用情况说明，提出下一步建议。"
        ],
        "expected_output": "准确承接两个不同问题，区分未证实有效与已证实无效，以给定事实限定判断，并允许提出明确的下一步建议。文章适配仍保持这些方法；不把源语料的数据库与断网词汇搬进新任务。",
        "comparison": "与同模型无风格基线比较；这种克制、证据导向的回答可能与默认文风接近，增量不明显时如实记录。"
      }
    }
  ],
  "generation_checks": [
    "核心正文、样例、证据和使用任务实际生成且引用可解析；结构通过单独报告。",
    "八维观察有依据或缺证说明；核心指导反向核对原句，观察方向、迁移推断及用户偏好可区分。",
    "跨题材样例迁移表达方法，能够改变原文命题；事实型任务有无需补充场景的写法。",
    "只按实际执行记录自查、独立装载和用户反馈的状态。"
  ]
}
